window.RP_SESSION={"id":"S-08c0166b6116","messages":[{"id":"RP-III-0141488","time":"2026-08-11T04:53:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"사소한 일이다. \n춤을 추고도 돈도 주지 않는 놈들은. \n술에 취해 허벅지를 만지는 놈들은.\n돈만 주면 내가 몸을 팔거라는 사람들은.\n괜찮다. 그럼에도 술꾼들 사이에서 춤을 춘다.\n술집에서의 평범한 하루다.","characters":[]},{"id":"RP-III-0141489","time":"2026-08-11T04:54:00+09:00","room":"RP III","name":"션","profile":"션","identity":"unresolved","type":"dialogue","body":"ㅎ ㅓ\n  ㄱ","characters":[]},{"id":"RP-III-0141490","time":"2026-08-11T04:54:00+09:00","room":"RP III","name":"션","profile":"션","identity":"unresolved","type":"dialogue","body":"나도 만지게 해다오.","characters":[]},{"id":"RP-III-0141491","time":"2026-08-11T04:54:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"돈 줘.","characters":[]},{"id":"RP-III-0141492","time":"2026-08-11T04:56:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"썩을 것들에게 둘러쌓여 있는 것도, 난? 난 괜찮다. \n그렇지만 아무렇지 않은 척 하는 것을 보러온 놈들이 아니지.\n인상을 찡그리고 불같이 화를 내는, 발을 동동 구르며 모든게 망했다며 남탓을 하는 나를 보고 싶은 거겠지?","characters":[]},{"id":"RP-III-0141493","time":"2026-08-11T04:56:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"기어이 들어주지.","characters":[]},{"id":"RP-III-0141494","time":"2026-08-11T04:56:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"언성.. 언성을 높이지 마라.","characters":[]},{"id":"RP-III-0141495","time":"2026-08-11T04:57:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"\"시끄러워! 술냄새 쩌는 놈들아. 너희 집에 처박힌 아내한테 그러시지?\"","characters":[]},{"id":"RP-III-0141496","time":"2026-08-11T04:58:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"내가 한놈을 콕 집어 삿대질로 구석에 몰때 사람들은 환호한다.","characters":[]},{"id":"RP-III-0141497","time":"2026-08-11T04:58:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"사람?","characters":[]},{"id":"RP-III-0141498","time":"2026-08-11T04:59:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"아니 내눈엔 그것들은 사람이 아니야. \n데미간도, 드워프도, 인간도, 엘프도 전부 전부 쓰레기일 뿐이야.","characters":[]},{"id":"RP-III-0141499","time":"2026-08-11T05:01:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"쓰레기를 기쁘게 해주는게 내 일이며, 쓰레기를 처리하는 것도 내 일이다.\n한참을 흥인지 화인지에 취해 춤을 추고 나면, 술에 취해 도망치는 쓰레기의 뒤를 따라.","characters":[]},{"id":"RP-III-0141500","time":"2026-08-11T05:01:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"내가 할 수 있는 최선의 선의를 보인다. 그게 전부다.","characters":[]},{"id":"RP-III-0141501","time":"2026-08-11T05:02:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"낮이 되고 나면, 정확히는 술집에 사람이 비면.","characters":[]},{"id":"RP-III-0141502","time":"2026-08-11T05:03:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"홀로 남은 의뢰인에게 돈을 받는다.","characters":[]},{"id":"RP-III-0141503","time":"2026-08-11T05:05:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"떠돌이 춤꾼에게 돈을 많이 주는 것은 바라지도 않는다.\n싼값에 부리는 것을 좋아하는 녀석들이다.\n난 한번도 의뢰인들의 얼굴을 똑바로 바라 본 적이 없다.\n날 싼값에 부리면서 내가 얼굴을 바라 볼 것이라고 기대하는 녀석들도 없다.","characters":[]},{"id":"RP-III-0141504","time":"2026-08-11T05:06:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"그날은 처음으로 날 고용한 놈의 얼굴을 바라봤다.\n왜냐고? 이유는 없다. \n고요한 새벽이 지나고 아침햇살이 어렴풋이 들어오면 빛을 피하기 위해 고개를 들었다고 치자.","characters":[]},{"id":"RP-III-0141505","time":"2026-08-11T05:07:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"나에게 미소를 짓는 의뢰인은, 아니 그 표정에는.","characters":[]},{"id":"RP-III-0141506","time":"2026-08-11T05:07:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"그 눈에는..","characters":[]},{"id":"RP-III-0141507","time":"2026-08-11T05:08:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"나도 쓰레기들과 다를 바 없으니까.","characters":[]},{"id":"RP-III-0141508","time":"2026-08-11T05:10:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"아침이 되고 다시 길을 나서는 떠돌이에게 길드에 대한 소문은 그다지 신경 쓸 일이 아니었다.\n길드라는 집에게 혼자 떠도는 사람은 좋은 인원이 아니다.","characters":[]},{"id":"RP-III-0141509","time":"2026-08-11T05:10:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"좋은 가족도 아니다..","characters":[]},{"id":"RP-III-0141510","time":"2026-08-11T05:11:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"돈만 준다면, 내가 좋은 인원이 아니어도 좋다. 좋은 가족이 아니어도 좋다.","characters":[]},{"id":"RP-III-0141511","time":"2026-08-11T05:12:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"날 그 녀석들처럼 바라보지 않았으니까. 아무렴.","characters":[]},{"id":"RP-III-0141512","time":"2026-08-11T05:12:00+09:00","room":"RP III","name":"오드리 프로필의 떠돌이 춤꾼","profile":"오드리","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0141513","time":"2026-08-11T05:12:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-III-0141514","time":"2026-08-11T10:01:00+09:00","room":"RP III","name":"카리엔","profile":"카리엔","identity":"unresolved","type":"dialogue","body":"https://youtu.be/IOXjm71Qfo8?si=J2RHx6MkwoUIue6H","characters":[]}]};
